sksl:
uniform shader image;
uniform float2 size;
uniform float amount;
uniform float horizontal;
uniform float vertical;
uniform float frequency;
uniform float phase;
uniform float centerX;
uniform float centerY;
uniform float radial;
uniform float stretch;
uniform float turbulence;
uniform float edgeMode;
uniform float effectOpacity;

float2 safeCoord(float2 p) {
    if (edgeMode < 0.5) {
        return clamp(p, float2(0.0), size);
    }
    if (edgeMode < 1.5) {
        return abs(mod(p, size * 2.0) - size);
    }
    return p;
}

half4 main(float2 coord) {
    float2 center = float2(centerX, centerY) * size;
    float2 p = coord - center;
    float distanceFromCenter = length(p);
    float phaseRad = phase * 0.0174532925;
    float wave = sin(distanceFromCenter * frequency * 0.01 + phaseRad);
    float radialWave = radial * wave * amount;
    float horizontalWave = sin(p.y * frequency * 0.01 + phaseRad) * horizontal * amount;
    float verticalWave = cos(p.x * frequency * 0.01 + phaseRad) * vertical * amount;
    float turbulenceX = sin(p.y * 0.035 + phaseRad * 2.0) * turbulence * amount * 0.01;
    float turbulenceY = cos(p.x * 0.035 + phaseRad * 2.0) * turbulence * amount * 0.01;
    float2 direction = normalize(p + float2(0.0001));
    float2 displacement = direction * radialWave + float2(horizontalWave, verticalWave) + float2(turbulenceX, turbulenceY);
    float2 warped = coord + displacement;
    warped.x += (warped.x - center.x) * stretch * 0.01;
    half4 original = image.eval(coord);
    half4 processed = image.eval(safeCoord(warped));
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
